    assert.deepEqual([(await getAdminImport(by, item.id)).item.publication, storage.copies, await db().collection('albums').countDocuments()], ['needsAttention', 1, 0]);
    await resumeAdminImportPublication(by, item.id, intent.operationId, storage);
