    assert.deepEqual([done.publication, storage.copies, done.published!.albumId, done.published!.artistIds, done.published!.organizationId], ['complete', 1, frozen.albumId, frozen.artists!.map(value => value.artistId), frozen.label!.organizationId]);
    assert.deepEqual(await counts(), { artists: 3, organizations: 1, albums: 1, audioTracks: 1, imageAssets: 0 });
