test('a reused entry Artist or label that changes or stops being ready before approval is stale at approval, writing nothing', async () => {
    const storage = new Storage(), dolor = new ObjectId(), label = new ObjectId();
    await db().collection('artists').insertOne({ _id: dolor, name: 'Dolor Soloist', bio: '', albumIds: [], visibility: 'public', lifecycleStatus: 'ready' });
    await db().collection('organizations').insertOne({ _id: label, name: 'Sit Records', organizationType: 'label', visibility: 'public', lifecycleStatus: 'ready' });
    let item = await reviewed(storage); const all = (await adminImportDuplicateCandidates(by, item.id)).items, pick = (id: ObjectId) => all.find(value => value.id === id.toHexString())!;
    item = await decided(item, { 'Dolor Soloist': reuse(pick(dolor)), label: reuse(pick(label)) });
    for (const [what, collection, id, change] of [
        ['a corrected featured Artist', 'artists', dolor, { visibility: 'hidden' }], ['a featured Artist being deleted', 'artists', dolor, { lifecycleStatus: 'deleting' }],
        ['a corrected label', 'organizations', label, { visibility: 'hidden' }], ['a label being deleted', 'organizations', label, { lifecycleStatus: 'deleting' }]
    ] as const) {
        await db().collection(collection).updateOne({ _id: id }, { $set: change });
        const before = await stored(item.id);
        await assert.rejects(publishAdminImport(by, item.id, approvalBody(item)), code('ADMIN_IMPORT_DUPLICATE_STALE'), what);
        assert.deepEqual(await stored(item.id), before, what);
        // Restored to its reviewed values, the record has its reviewed revision again.
        await db().collection(collection).updateOne({ _id: id }, { $set: { visibility: 'public', lifecycleStatus: 'ready' } });
    }
    const done = await publishNow(storage, item);
    assert.deepEqual([done.publication, done.published!.artistIds[2], done.published!.organizationId], ['complete', dolor.toHexString(), label.toHexString()]);
    assert.deepEqual(await counts(), { artists: 3, organizations: 1, albums: 1, audioTracks: 1, imageAssets: 0 });
});

